mapper.select:
select
c1.C_Name as saContractorName, c2.C_Name as saSupervisorName, c3.C_Name as saCostConsultName, c1.C_Name_History as saContractorNameHistory, c2.C_Name_History as saSupervisorNameHistory, c3.C_Name_History as saCostConsultNameHistory, c4.C_Name as saReviewUnitName, case when mn.Sa_Is_Sub_Contract='02' then sr.Sc_Name else con.con_Name end as conName, case when mn.Sa_Is_Sub_Contract='02' then sr.Sc_Money else con.con_Money_Total end as conMoneyTotal, case when mn.Sa_Is_Sub_Contract='02' then sr.Sc_Type else con.con_Type end as conType, case when mn.Sa_Is_Sub_Contract='02' then sr.Sc_Code else con.con_Code end as conCode, mn.* from Inv_Settlement_Apply mn left join Con_Contract con on con.Con_Id=mn.Con_Id left join SYS_Company c1 on mn.Sa_Contractor=c1.C_Id left join SYS_Company c2 on mn.Sa_Supervisor=c2.C_Id left join SYS_Company c3 on mn.Sa_Cost_Consult=c3.C_Id left join SYS_Company c4 on mn.Sa_Review_Unit=c4.C_Id left join Subcontract_Record sr on mn.Con_Id=sr.Sc_Id
${params.authSql}
and mn.Te_Id = #{params.teId}
and mn.P_Id=#{params.pId}
and mn.Con_Id = #{params.conId}
and mn.Sa_Cu_Af = #{params.saCuAf}
and mn.Sa_Historical = #{params.saHistorical}
and mn.Sa_State = #{params.saState}
and mn.Sa_Submission_User like concat('%',#{params.saSubmissionUser},'%')
and mn.Sa_Submission_Phone like concat('%',#{params.saSubmissionPhone},'%')
and mn.Sa_Examine_User like concat('%',#{params.saExamineUser},'%')
and mn.Sa_Examine_Phone like concat('%',#{params.saExaminePhone},'%')
and mn.Sa_Con_Code like concat('%',#{params.saConCode},'%')
and con.Con_Name like concat('%',#{params.conName},'%')
and mn.Sa_Create_Uname like concat('%',#{params.saCreateUname},'%')
and c1.C_Name like concat('%',#{params.saContractorName},'%')
and mn.sa_Create_Time > #{params.saCreateDateStart}
and mn.sa_Create_Time < #{params.saCreateDateEnd}
and likePname(#{params.pName},pro.P_Id)=true
and pro.P_Name like concat('%',#{params.pName},'%')
and mn.Sa_Cost_Consult is not null
and mn.Sa_Cost_Consult is null
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Sa_Create_Time DESC

select mn.*,ccc.confirm_serial_number as confirmSerialNumber ,ccc.Construction_Contractor as constructionContractor ,sc3.C_NAME as constructionContractorName ,ccc.Construction_Image as constructionImage ,ccc.Construction_Drawing as constructionDrawing ,ccc.Audit_Unit as auditUnit ,sc2.C_NAME as auditUnitName from Inv_Settlement_Apply mn left join construction_completion_confirm ccc on ccc.id = mn.completion_confirm_id left join sys_company sc3 on sc3.C_ID = ccc.Construction_Contractor left join sys_company sc2 on sc2.C_ID = ccc.Audit_Unit
and ccc.confirm_serial_number like concat('%',#{params.confirmSerialNumber},'%')
and mn.Sa_Serial_Number like concat('%',#{params.saSerialNumber},'%')
and mn.Sa_State = #{params.saState}
and mn.Sa_Create_Time between #{params.createTimeRange[0]} and #{params.createTimeRange[1]}
and mn.Sa_Id not in (select distinct isp.inv_settlement_apply_id from inv_settlement_pay isp where isp.state!=3)
and sc3.C_NAME like concat('%',#{params.constructionContractorName},'%')
and mn.sa_title like concat('%',#{params.saTitle},'%')
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Sa_Create_Time desc
